from typing import Set
import random

def load_dictionary() -> Set[str]:
    # Implement loading dictionary from a file or database
    dictionary = set()
    try:
        with open("wordle/dictionary.txt", "r") as file:
            for line in file:
                dictionary.add(line.strip().upper())
    except FileNotFoundError:
        print("Dictionary file not found. Using default dictionary.")
        # Add default dictionary words
        dictionary.add("HELLO")
        dictionary.add("WORLD")
    return dictionary


def is_valid_word(word: str) -> bool:
    dictionary = load_dictionary()
    return word.upper() in dictionary and len(word) == 5


def get_random_word() -> str:
    dictionary = load_dictionary()
    return random.choice(list(dictionary))


def normalize_word(word: str) -> str:
    return word.strip().upper()
